export var BUNDLED = {"aida":{"v":1,"slug":"aida","title":"Aida","match":["Aida"],"facts":[["aida-01","p","","","Aida was commissioned by Cairo’s Khedivial Opera House and premiered there on 24 December 1871.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida"],["aida-02","b","","","The premiere was delayed because the sets and costumes were stuck in Paris during the Prussian siege of 1870–71.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida"],["aida-03","c","","","Verdi didn’t go to Cairo. He disliked that the audience was all invited dignitaries and critics, and counted the 1872 La Scala opening as the real premiere.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Cairo_premiere_and_initial_success_in_Italy"],["aida-04","c","Prelud|Preludio","","Verdi wrote a full overture to replace this short prelude, then dropped it for its “pretentious silliness” (his own words).","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Cairo_premiere_and_initial_success_in_Italy"],["aida-05","h","Prelud|Preludio","","Verdi’s rejected Aida overture got a rare broadcast in 1940 from Toscanini and the NBC Symphony, but was never released commercially.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Cairo_premiere_and_initial_success_in_Italy"],["aida-06","h","","","Verdi agreed to write Aida, on a story idea by the Egyptologist Auguste Mariette, for 150,000 francs.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida"],["aida-07","s","","","Auguste Mariette designed the costumes for the Cairo premiere; the sets were painted in Paris by the Opéra’s scene painters.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Cairo_premiere_and_initial_success_in_Italy"],["aida-08","a","Ritorna vincitor|O patria mia","","Verdi wrote the role of Aida for Teresa Stolz, who first sang it at the Milan premiere.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Cairo_premiere_and_initial_success_in_Italy"],["aida-09","a","Amneris|Fu la sorte|Ohimè! morir mi sento|L.abborrita rivale","","Maria Waldmann, the Milan Amneris, was Verdi’s favourite in the role; she sang it many times at his request.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Cairo_premiere_and_initial_success_in_Italy"],["aida-10","b","","","In Rio de Janeiro in 1886, after the conductor and two replacements failed, a 19-year-old cellist named Arturo Toscanini conducted Aida from memory, with great success.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Other_19th-century_performances"],["aida-11","h","","","At the Met alone, Aida has been sung more than 1,100 times since 1886.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida"],["aida-12","h","","","Aida reached the Met on 12 November 1886, conducted by Anton Seidl.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Other_19th-century_performances"],["aida-13","m","Su! del Nilo|Guerra","","The King names Radamès commander, and the court erupts: “Su! del Nilo al sacro lido”, then “Guerra, guerra, guerra!”","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Act_1"],["aida-14","m","Possente|Ptah|Fthà","","Solemn ceremonies and priestesses’ dances in the temple: “Possente Ptah”.","Wikipedia, “Aida”","https://en.wikipedia.org/wiki/Aida#Act_1"]]},"boheme":{"v":1,"slug":"boheme","title":"La Bohème","match":["La Bohème","La Boheme"],"facts":[["bohe-01","h","^Opening\\ Credits$","perf:982c4ee8","Today’s matinee is the Met’s 1,415th Bohème. The first was on 26 December 1900, with Nellie Melba as Mimì.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0387831","Met milestone",20,1],["bohe-02","a","^Introduction\\ by\\ Matthew\\ Polenzani$","perf:982c4ee8","Host Matthew Polenzani knows this garret: the tenor has sung La Bohème at the Gran Teatre del Liceu.",null,"https://en.wikipedia.org/wiki/Matthew_Polenzani","Your host",20,1],["bohe-03","s","Questo Mar Rosso","production:1981-12-14","Zeffirelli’s garret: a cutaway attic perched on the Paris rooftops, complete with tiles and smoking chimney pots.","Thor Eckert Jr., The Christian Science Monitor, on this production’s Met premiere, 14 Dec 1981","https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377459","Set piece",20,1],["bohe-04","a","^Act\\ I:\\ Questo\\ Mar\\ Rosso$","perf:982c4ee8","Our Marcello, Lucas Meachem, got his big break in 2006, discovered by Susan Graham at a karaoke bar. In Paris.",null,"https://en.wikipedia.org/wiki/Lucas_Meachem","Did you know?",150,1],["bohe-05","h","Abbasso, abbasso","","Bohème’s premiere, Turin, 1 February 1896, was conducted by a 28-year-old Arturo Toscanini.",null,"https://en.wikipedia.org/wiki/La_boh%C3%A8me","Meanwhile, in 1896…",20,1],["bohe-07","a","^Act\\ I:\\ Non\\ sono\\ in\\ vena\\ $","perf:982c4ee8","Juliana Grigoryan, our Mimì, won first and audience prizes at Operalia 2022. Her Met debut: Liù, in 2024.",null,"https://en.wikipedia.org/wiki/Juliana_Grigoryan","Rising star",20,1],["bohe-06","c","Si sente meglio","","Puccini on this opera: “I lived that Bohème”, as a poor student, short of food, clothes and rent.",null,"https://en.wikipedia.org/wiki/Giacomo_Puccini","Composer’s verdict",20,1],["bohe-08","m","Che gelida manina","","“Che gelida manina” comes in three paragraphs: tender, then bolder at “Chi son? Sono un poeta”, then the love motif.",null,"https://en.wikipedia.org/wiki/Che_gelida_manina","Listen for it",20,1],["bohe-09","m","Che gelida manina","","Listen for the climactic high C on “speranza”: it’s unwritten, not in Puccini’s score.",null,"https://en.wikipedia.org/wiki/Che_gelida_manina","Fun fact",120,1],["bohe-10","a","^Act\\ I:\\ Sì\\.\\ Mi\\ chiamano\\ Mimì$","perf:982c4ee8","Our Rodolfo, Freddie De Tommaso, entered London’s Royal Academy of Music as a baritone, then became a tenor.",null,"https://en.wikipedia.org/wiki/Freddie_De_Tommaso","Voice change",20,1],["bohe-11","m","O soave fanciulla","","As they realize they’re in love, the love motif from “Che gelida manina” returns.",null,"https://en.wikipedia.org/wiki/O_soave_fanciulla","Listen for it",20,1],["bohe-12","m","O soave fanciulla","","The ending: Mimì’s high C, marked “fading away”, over descending harp harmonics. A major has become C major.",null,"https://en.wikipedia.org/wiki/O_soave_fanciulla","Listen for it",130,1],["bohe-13","s","Aranci, datteri","production:1981-12-14","When this Act II set was unveiled in 1981, the audience roared for nearly a minute.","Thor Eckert Jr., The Christian Science Monitor, on this production’s Met premiere, 14 Dec 1981","https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377459","Showstopper",20,1],["bohe-14","r","Chi guardi","production:1981-12-14","A stilt walker, a dancing bear, Musetta’s horse-drawn cab: “a Delacroix riot of reds and golds.”","Charles Michener, Newsweek, 28 Dec 1981, on this production’s Met premiere","https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377459","Critics: big fans",20,1],["bohe-15","a","^Act\\ II:\\ Viva\\ Parpignol!\\ $","perf:982c4ee8","Conductor Keri-Lynn Wilson made her Met debut in 2022–23. She also founded the Ukrainian Freedom Orchestra.",null,"https://en.wikipedia.org/wiki/Keri-Lynn_Wilson","On the podium",20,1],["bohe-16","m","Quando me","","Musetta’s Waltz is aimed at the people in the café as much as at us in the theater.",null,"https://en.wikipedia.org/wiki/Quando_me'n_vo'","Listen for it",20,1],["bohe-17","a","^Act\\ II:\\ Quando\\ me'n\\ vo'\\ \\(Musetta's\\ Waltz\\)$","perf:982c4ee8","Heidi Stober began as a pianist and first planned to teach choral music. Then came opera.",null,"https://en.wikipedia.org/wiki/Heidi_Stober","Musetta, today",150,1],["bohe-18","s","Chi l'ha richiesto","production:1981-12-14","The act ends in a parade. At the 1981 premiere it brought some 240 people onto the Met stage.","Thor Eckert Jr., The Christian Science Monitor, on this production’s Met premiere, 14 Dec 1981","https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377459","Crowd count",20,1],["bohe-19","s","le guardie","production:1981-12-14","Watch the tavern door: a man in black rushes out, opens a black umbrella, and vanishes into the snow.","Charles Michener, Newsweek, 28 Dec 1981, on this production’s Met premiere, calling it a “ghostly bit of stage business”","https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377459","Director’s touch",20,1],["bohe-20","m","Dunque è proprio finita","","Two couples, two moods: Mimì and Rodolfo part tenderly while Marcello and Musetta quarrel fiercely.",null,"https://en.wikipedia.org/wiki/La_boh%C3%A8me","Listen for it",120,1],["bohe-21","s","In un coupé","production:1981-12-14","Check the sky behind the garret: silver-gray in Act I, rosy-peach now in Act IV.","Charles Michener, Newsweek, 28 Dec 1981, on this production’s Met premiere","https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377459","Set piece",20,1],["bohe-22","s","Gavotta","production:1981-12-14","Zeffirelli turns Colline and Schaunard’s mock duel into a mad scamper along the rooftops.","Charles Michener, Newsweek, 28 Dec 1981, on this production’s Met premiere","https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377459","Director’s touch",10,1],["bohe-23","a","^Act\\ IV:\\ Vecchia\\ zimarra$","perf:982c4ee8","Jongmin Park bids farewell to Colline’s coat. He made his Covent Garden debut in this very role, in 2014.",null,"https://en.wikipedia.org/wiki/Jongmin_Park","Colline, today",20,1],["bohe-24","h","Schaunard, ognuno","production:1981-12-14","Bohème closed the old Met house in April 1966. Zeffirelli then staged the new house’s very first production.",null,"https://en.wikipedia.org/wiki/La_boh%C3%A8me","Met history",20,1]],"gap":60},"butterfly":{"v":1,"slug":"butterfly","title":"Madama Butterfly","match":["Madama Butterfly"],"facts":[["butterfly-01","p","","","Madama Butterfly premiered at La Scala on 17 February 1904 in a two-act version, and was withdrawn after a disastrous first night.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly"],["butterfly-02","b","","","At the 1904 premiere, audience plants were given nightingale whistles for the sunrise. The audience took it as a cue to make animal noises of their own.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Reception"],["butterfly-03","p","","","The premiere was called “one of the most terrible flops in the history of Italian opera”. One problem: no intermission in the very long second act.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Reception"],["butterfly-04","c","","","Puccini’s sister Ramelde wrote that night: “The second act I didn’t hear at all, and before the opera was over, we ran out of the theater.”","Ramelde Puccini, letter to her husband, 1904 (via Wikipedia)","https://en.wikipedia.org/wiki/Madama_Butterfly#Reception"],["butterfly-05","h","","","Puccini rewrote it, splitting the long second act in two. The new version was a great success in Brescia on 28 May 1904.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly"],["butterfly-06","m","Humming|Coro a bocca chiusa|bocca chiusa","","The Humming Chorus became the bridge between Puccini’s new Acts II and III.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly"],["butterfly-07","h","","","There are five versions of Butterfly. Puccini’s final 1907 revision, the “Standard Version”, is the one usually performed.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Versions"],["butterfly-08","h","","","Butterfly reached the Metropolitan Opera on 11 February 1907, in Puccini’s third version.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Versions"],["butterfly-09","h","","","The first US performances, in 1906, were in English, by Henry Savage’s touring company.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Performance_history"],["butterfly-10","m","Bimba dagli occhi|Vogliatemi bene","","From the long love duet that closes Act I: “Bimba dagli occhi pieni di malia”, “Sweetheart, with eyes full of enchantment”.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Act_1"],["butterfly-11","m","Ora a noi|Sharpless|lettera","","Sharpless brings a letter from Pinkerton asking him to break the news that he isn’t coming back to Japan.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Act_2"],["butterfly-12","m","Il cannone|Scuoti quella fronda","","“Il cannone del porto!”, the cannon at the harbor, leads into the famous Flower Duet.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Act_2"],["butterfly-13","h","","","The musical Miss Saigon (1989) was inspired by Madama Butterfly.","Wikipedia, “Madama Butterfly”","https://en.wikipedia.org/wiki/Madama_Butterfly#Adaptations"]]},"carmen":{"v":1,"slug":"carmen","title":"Carmen","match":["Carmen"],"facts":[["carm-01","h","^Opening\\ Credits$","perf:f6b88373","Today’s matinee is the Met’s 1,033rd Carmen. The first, on 9 January 1884, drew mixed reviews.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0387422","Met milestone",20,1],["carm-02","m","Act I: Prelude","","The prelude braids three themes: the bullfighters’ entry, the Toreador refrain, and the motif of Carmen and her fate.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",15,1],["carm-03","s","Sur la place","production:2023-12-31","Director Carrie Cracknell (Netflix’s Persuasion) made her Met debut with this staging, at the 2023 New Year’s Eve gala.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0387396","Director’s cut",20,1],["carm-04","a","^Act\\ I:\\ Sur\\ la\\ place,\\ chacun\\ passe$","perf:f6b88373","Micaëla today: Angel Blue. Met debut in 2017, as Mimì; later a Grammy for the Met’s Porgy and Bess.",null,"https://en.wikipedia.org/wiki/Angel_Blue","Star turn",150,1],["carm-05","a","^Act\\ I:\\ Avec\\ la\\ garde\\ montante$","perf:f6b88373","Kids’ chorus on the march: conductor Daniele Rustioni sang in La Scala’s boys choir as a child.",null,"https://en.wikipedia.org/wiki/Daniele_Rustioni","Full circle",20,1],["carm-06","c","La cloche a sonne","","Bizet never visited Spain. For Spanish flavor, he went looking for authentic ethnic material.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Did you know?",20,1],["carm-07","m","Mais nous ne voyons pas","","Hear that brief phrase? The fate motif announces Carmen’s entrance.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",3,1],["carm-08","m","Habanera","","Bizet thought the Habanera tune was a folk song. It was by Sebastián Iradier; Bizet credited him in the score.",null,"https://en.wikipedia.org/wiki/Habanera_(aria)","Borrowed!",20,1],["carm-09","m","Habanera","","Under the Habanera: a pedal D held throughout, triplets in the voice, and the flute in its low register.",null,"https://en.wikipedia.org/wiki/Habanera_(aria)","Listen for it",120,1],["carm-10","a","^Act\\ I:\\ Carmen!\\ Sur\\ tes\\ pas\\ nous\\ nous\\ pressons\\ tous!$","perf:f6b88373","Aigul Akhmetshina, born in Bashkortostan in 1996, also sang Carmen on this staging’s opening night.",null,"https://en.wikipedia.org/wiki/Aigul_Akhmetshina","Rising star",3,1],["carm-11","a","^Act\\ I:\\ Jose!\\ Micaela!—Ma\\ mere\\ je\\ la\\ vois!$","perf:f6b88373","Piotr Beczała, our Don José, made his Met debut on 19 December 2006, as the Duke in Rigoletto.",null,"https://en.wikipedia.org/wiki/Piotr_Becza%C5%82a","Met debut",20,1],["carm-12","m","Seguidilla","","The Seguidilla borrows flamenco rhythms and instruments, and drives José to an exasperated high A-sharp shout.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",20,1],["carm-13","m","Voici l'ordre","","Before Carmen escapes, a disconcerting fragment of the Habanera returns. Bizet revised this finale several times.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",20,1],["carm-14","m","Act II: Entracte","","This entr’acte is built on the melody José will soon sing offstage, on his way back to Carmen.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",10,1],["carm-15","m","Toreador Song","","Escamillo’s entrance: brass and percussion up front, with the crowd singing along.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",20,1],["carm-16","a","^Act\\ II:\\ Nous\\ avons\\ en\\ tête\\ une\\ affaire$","perf:f6b88373","Kyle Ketelsen, our Escamillo, joined the Army National Guard planning to fly helicopters. Iowa’s music faculty changed that.",null,"https://en.wikipedia.org/wiki/Kyle_Ketelsen","Plot twist",20,1],["carm-17","m","Je vais danser","","Carmen dances with castanets while a distant cornet calls José to duty, blended into her melody, barely audible.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",20,1],["carm-18","m","La fleur que tu","","A muted fate motif on English horn leads in. The Flower Song ends pianissimo, on a sustained high B-flat.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",5,1],["carm-19","m","Holà! Carmen! Holà","","José is swept into the smugglers’ life, and the act closes on a triumphant hymn to freedom.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",200,1],["carm-20","m","Act III: Entracte","","This entr’acte was first meant for Bizet’s L’Arlésienne. Listen to the woodwinds dialogue and intertwine.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Borrowed!",10,1],["carm-21","m","Card Trio","","The card trio turns ominous when Carmen joins in: the fate motif underlines her premonition of death.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",120,1],["carm-22","m","C'est des contrebandiers","","Micaëla’s aria is framed by horn calls, before and after: listen for them.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",5,1],["carm-23","m","Holà! José","","As Escamillo leaves, his offstage Toreador refrain sounds confident against José’s growing desperation.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",380,1],["carm-24","m","Act IV: Entracte","","Act IV’s lively entr’acte comes from El criado fingido, a short operetta by Manuel García.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Borrowed!",10,1],["carm-25","m","Voici la quadrille","","Here come the bullfighters: their march is led by the children’s chorus.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",20,1],["carm-26","m","Tu ne m'aimes donc plus","","As José kills Carmen, the Toreador refrain rings offstage and the fate motif sounds fortissimo.",null,"https://en.wikipedia.org/wiki/Carmen#Music","Listen for it",240,1]],"gap":60},"figaro":{"v":1,"slug":"figaro","title":"Le Nozze di Figaro","match":["Le Nozze di Figaro","The Marriage of Figaro","Nozze di Figaro"],"facts":[["figa-01","h","^Opening\\ Credits$","perf:697a3182","Today’s matinee is the Met’s 528th Le Nozze di Figaro.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0387726","Met milestone",20,1],["figa-02","a","^Introduction\\ by\\ Julia\\ Bullock$","perf:697a3182","Host Julia Bullock debuted at the Met in 2024, in El Niño by John Adams, who calls her his muse.",null,"https://en.wikipedia.org/wiki/Julia_Bullock","Your host",20,1],["figa-03","a","^Overture$","perf:697a3182","Joana Mallwitz makes her Met debut with this Figaro. Her first professional conducting job came at six hours’ notice.",null,"https://en.wikipedia.org/wiki/Joana_Mallwitz","Met debut",20,1],["figa-04","p","Overture","","At the 1786 premiere, the audience demanded encores of five numbers. On 8 May, seven.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Encore!",160,1],["figa-05","s","Cinque","production:2014-09-22","Richard Eyre’s staging opened the Met’s 2014–15 season, with James Levine conducting.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0385503","Director’s cut",20,1],["figa-06","h","Se a caso","","It was Mozart who picked Beaumarchais’s play. Da Ponte turned it into a libretto in six weeks.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Did you know?",20,1],["figa-07","h","Se vuol ballare","","Servant versus count: Beaumarchais’s play, with its frank class conflict, was at first banned in Vienna.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Banned!",20,1],["figa-08","m","Cosa sento","","Basilio’s phrase “Così fan tutte le belle” here later turned up in the overture to Mozart’s Così fan tutte.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Listen for it",60,1],["figa-09","m","Non più andrai","","A C-major military march: the tune mimics a bugle on natural harmonics, and the horns join in.",null,"https://en.wikipedia.org/wiki/Non_pi%C3%B9_andrai","Listen for it",20,1],["figa-10","m","Non più andrai","","Mozart quoted this tune in Don Giovanni, where Leporello sighs: “Now that tune I know too well.”",null,"https://en.wikipedia.org/wiki/Non_pi%C3%B9_andrai","Recycled",140,1],["figa-11","m","Porgi amor","","“Porgi, amor” reuses the motif that opens Mozart’s early bassoon concerto.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Recycled",20,1],["figa-12","a","^Act\\ II:\\ Vieni,\\ cara\\ Susanna$","perf:697a3182","Federica Lombardi, our Countess, debuted at the Met in 2019 as Donna Elvira; at Covent Garden, as this Countess.",null,"https://en.wikipedia.org/wiki/Federica_Lombardi","Star turn",20,1],["figa-13","h","Venite, inginocchiatevi","","In 1789 Mozart replaced this aria for a new Susanna. The Met used his replacements in 1998, with Cecilia Bartoli.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Met history",20,1],["figa-14","m","Esci omai","","The Act II finale starts here: over 900 bars of continuous music, one of Mozart’s longest uninterrupted stretches.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Settle in",20,1],["figa-15","m","Ah! signor! signor!","","Count the voices: eight of the opera’s 11 characters pile in, climaxing in a seven- and eight-voice tutti.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Listen for it",20,1],["figa-16","m","Dove sono","","“Dove sono” begins like the Agnus Dei of Mozart’s Coronation Mass, moved from F major to C major.",null,"https://en.wikipedia.org/wiki/Dove_sono","Recycled",20,1],["figa-17","m","Dove sono","","Oboes and bassoons fill the Countess’s rests with expressive motifs, which she later picks up.",null,"https://en.wikipedia.org/wiki/Dove_sono","Listen for it",150,1],["figa-18","m","^Act\\ III:\\ Riconosci\\ in\\ questo\\ amplesso$","perf:697a3182","Today “Dove sono” came before this sextet. Mozart’s score puts it after; two scholars argued this order is more logical.",null,"https://en.wikipedia.org/wiki/Dove_sono","Running order",20,1],["figa-19","m","Sull'aria","","The letter duet: B-flat major, 6/8, oboe and bassoon. The Countess dictates; Susanna repeats each line as she writes.",null,"https://en.wikipedia.org/wiki/Sull'aria_..._che_soave_zeffiretto","Listen for it",20,1],["figa-20","s","Queste sono, Madama","production:2014-09-22","In this production, the two peasant girls’ music is sung by Barbarina and Cherubino.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0385503","Staging note",20,1],["figa-21","h","Tutto è disposto","","Da Ponte swapped Figaro’s climactic speech against inherited nobility for an equally angry aria against unfaithful wives.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Rewritten",10,1],["figa-22","m","Aprite un po","","Hear the two horns playing together? That’s Mozart’s joke for cuckoldry. Verdi borrowed it in Falstaff.",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Listen for it",60,1],["figa-23","a","^Act\\ IV:\\ Deh\\ vieni\\ non\\ tardar$","perf:697a3182","Olga Kulchynska, our Susanna, learned three days ahead she’d sing the Bolshoi premiere of The Tsar’s Bride.",null,"https://en.wikipedia.org/wiki/Olga_Kulchynska","Fast start",60,1],["figa-24","m","Gente, gente","","Listen for the Count’s plea, “Contessa, perdono!” Her reply: “I am kinder, and I say yes.”",null,"https://en.wikipedia.org/wiki/The_Marriage_of_Figaro","Listen for it",150,1]],"gap":60},"flute":{"v":1,"slug":"flute","title":"The Magic Flute","match":["The Magic Flute","Die Zauberflöte","Die Zauberflote"],"facts":[["flute-01","p","","","The Magic Flute premiered on 30 September 1791 in Vienna, just two months before Mozart’s death.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute"],["flute-02","p","","","At the premiere Mozart conducted, the librettist Schikaneder played Papageno himself, and the Queen of the Night was sung by Mozart’s sister-in-law, Josepha Hofer.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Premiere_and_reception"],["flute-03","c","","","Mozart to his wife on 7 October 1791: “I have this moment returned from the opera, which was as full as ever … what always gives me the most pleasure is the silent approval!”","Mozart, letter to Constanze (via Wikipedia)","https://en.wikipedia.org/wiki/The_Magic_Flute#Premiere_and_reception"],["flute-04","c","","","Mozart went to hear his new opera almost every night, taking along friends and relatives.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Premiere_and_reception"],["flute-05","h","","","The opera reached its 100th performance in November 1792, but Mozart didn’t live to see it: he died on 5 December 1791.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Premiere_and_reception"],["flute-06","m","Overture|Ouvert","","The overture was written after the rest of the opera. Its three solemn brass chords nod to Freemasonry, where the number three is highly significant.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Overture"],["flute-07","h","","","Both Mozart and Schikaneder were Freemasons, and the opera is noted for its Masonic elements.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Themes"],["flute-08","m","Der Vogelfänger|Vogelfanger|Papageno","","Papageno’s whistle is based on a motif borrowed from a concerto by Antonio Salieri.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Composition"],["flute-09","m","Pa-?pa-?pa|Papagena","","The Papageno–Papagena duet, with its bird-like syllables, resembles a comic cavatina in Salieri’s Prima la musica e poi le parole.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Composition"],["flute-10","m","Das klinget|Glockenspiel|bells","","Mozart called for a “stromento d’acciaio” (instrument of steel) to play Papageno’s magic bells.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Orchestration"],["flute-11","m","Der, welcher wandert|Armed Men|armou?red men|Geharnischte","","The Armed Men’s chorale is set to a Baroque chorale prelude, inspired by Martin Luther’s hymn “Ach Gott, vom Himmel sieh darein”.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Scene_7:_At_the_Mountains_of_Ordeal"],["flute-12","r","","","Pauline Kael called it “a peerlessly silly masterpiece: sublimely lucid music arising out of a parodistic fairy tale.”","Pauline Kael (via Wikipedia)","https://en.wikipedia.org/wiki/The_Magic_Flute#Premiere_and_reception"],["flute-13","h","Der Hölle Rache|Der Holle Rache|O zittre nicht","","Some see the Queen of the Night as a portrait of Empress Maria Theresa, who banned Freemasonry from Austria.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Themes"],["flute-14","h","","","Early productions were often of highly altered, sometimes even mutilated, versions of the opera.","Wikipedia, “The Magic Flute”","https://en.wikipedia.org/wiki/The_Magic_Flute#Premiere_and_reception"]]},"giovanni":{"v":1,"slug":"giovanni","title":"Don Giovanni","match":["Don Giovanni"],"facts":[["giovanni-01","p","","","Don Giovanni premiered in Prague at the National Theatre (today’s Estates Theatre) on 29 October 1787.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni"],["giovanni-02","b","","","It was meant to open on 14 October 1787 for a visiting archduchess, but wasn’t ready, so Le Nozze di Figaro was played instead.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Composition_and_premiere"],["giovanni-03","h","","","Prague commissioned it after Mozart’s successful visit there in early 1787.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Composition_and_premiere"],["giovanni-04","m","Overture|Sinfonia","","The overture opens with a thundering D minor cadence and a mysterious passage, then turns into a light-hearted D major allegro.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Act_1"],["giovanni-05","m","Madamina|catalogo","","The Catalogue Aria counts the Don’s conquests: 640 in Italy, 231 in Germany, 100 in France, 91 in Turkey, and in Spain, 1,003.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Act_1"],["giovanni-06","h","Madamina|catalogo","","Thanks to this aria, German and other languages call fold-out brochures a “Leporello list”.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Cultural_influence"],["giovanni-07","m","Là ci darem|La ci darem","","“Là ci darem la mano” (“There we will entwine our hands”): alone with Zerlina, the Don immediately turns on the charm.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Act_1"],["giovanni-08","m","Fin ch.han dal vino","","The “Champagne Aria”: the Don orders a party with every girl Leporello can find.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Act_1"],["giovanni-09","c","Dalla sua pace","","Mozart added “Dalla sua pace” for the 1788 Vienna production, written for the tenor Francesco Morella.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Revision_for_Vienna"],["giovanni-10","c","Mi tradì|In quali eccessi","","Elvira’s “Mi tradì quell’alma ingrata” was also a Vienna addition, composed on 30 April 1788 for Caterina Cavalieri.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Revision_for_Vienna"],["giovanni-11","s","Don Giovanni, a cenar|cenar teco|Commendatore","","In Prague and Vienna one singer played both Masetto and the Commendatore. The demons’ chorus gave him just a little time to change costume.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Later_performance_traditions"],["giovanni-12","h","Questo è il fin|Questo e il fin|Ah, dov.è il perfido","","A memoirist claimed the final ensemble was heard only at the first Prague performance, then never again during the original run. Today it is almost always performed.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Later_performance_traditions"],["giovanni-13","r","","","Kierkegaard argued that “among all classic works Don Giovanni stands highest.” Gounod called it “a work without blemish, of uninterrupted perfection”.","Wikipedia, “Don Giovanni”","https://en.wikipedia.org/wiki/Don_Giovanni#Cultural_influence"]]},"idomeneo":{"v":1,"slug":"idomeneo","title":"Idomeneo","match":["Idomeneo"],"facts":[["ido-c01","h","^Opening\\ Credits$","perf:19a5ae2a","Today’s matinee is the Met’s 73rd Idomeneo. The very first, in 1982, opened this same Ponnelle production.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0386164","Met milestone",6,1],["ido-c02","a","^Introduction\\ by\\ Eric\\ Owens$","perf:19a5ae2a","Your host, Eric Owens, isn’t just hosting: he’s also the offstage Voice of Neptune in Act III.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0386164","Double duty",30,1],["ido-c03","a","^Overture$","perf:19a5ae2a","James Levine led the Met’s first Idomeneo in 1982 and leads today’s, No. 73. His Met total: 2,577 performances.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377675","Full circle",20,1],["ido-c04","m","Quando avran fine","","The overture’s soft final chords were a setup: they lead straight into G minor, the key of Ilia’s scene.",null,"https://en.wikipedia.org/wiki/Idomeneo#Overture","Listen for it",20,1],["ido-m2","m","Quando avran fine","","Recitative comes two ways here: “secco”, with just harpsichord and cello, and orchestral “accompagnato”, which Mozart handles masterfully.",null,"https://en.wikipedia.org/wiki/Idomeneo","Listen for it",120,1],["ido-c05","a","^Act\\ I:\\ Padre,\\ germani,\\ addio!$","perf:19a5ae2a","Nadine Sierra, our Ilia, was 28 at this matinee. 2017 was also her Richard Tucker Award year.",null,"https://en.wikipedia.org/wiki/Nadine_Sierra","Rising star",25,1],["ido-c06","a","^Act\\ I:\\ Non\\ ho\\ colpa$","perf:19a5ae2a","Mozart wrote Idamante for a castrato. Alice Coote, known for trouser roles, also sang him in San Francisco in 2008.",null,"https://en.wikipedia.org/wiki/Idomeneo#Performance_history","Trouser role",25,1],["ido-c08","m","Tutte nel cor","","Elettra, jealous of Ilia: “I can feel you all in my heart, furies of the dark hell.”","Varesco’s libretto (English translation)","https://en.wikipedia.org/wiki/Idomeneo#List_of_arias","Translation",20,1],["ido-m3","m","Numi, piet","","Shipwreck! Mozart builds this scene almost exactly like the storm scene in Gluck’s Iphigénie en Tauride.",null,"https://en.wikipedia.org/wiki/Idomeneo#Composition","Echoes of Gluck",15,1],["ido-c10","a","^Act\\ I:\\ Vedrommi\\ intorno$","perf:19a5ae2a","Matthew Polenzani made his Met debut in 1997, in Boris Godunov, and has since sung over 300 performances here.",null,"https://en.wikipedia.org/wiki/Matthew_Polenzani","Met veteran",25,1],["ido-c11","s","Il padre adorato","production:1982-10-14","Ponnelle filmed La Cenerentola with Frederica von Stade in 1981. A year later she was his first Met Idamante.",null,"https://en.wikipedia.org/wiki/Jean-Pierre_Ponnelle","Ponnelle & co.",20,1],["ido-c12","c","Intermezzo: Marcia","","Mozart was 24 when he wrote Idomeneo, his third opera seria, for the Munich court carnival.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377675","Meanwhile, in 1780…",15,1],["ido-c13","s","Siam soli","production:1982-10-14","Ponnelle’s frame: classical Roman columns, a broad flight of steps, and shifting backdrops of Piranesi-style ruins.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377675","Set piece",25,1],["ido-c14","a","^Act\\ II:\\ Se\\ il\\ tuo\\ duol$","perf:19a5ae2a","Arbace today: British baritone Alan Opie, who shared Grammys for recordings of Peter Grimes and Die Meistersinger.",null,"https://en.wikipedia.org/wiki/Alan_Opie","Did you know?",25,1],["ido-m5","m","Se il padre perdei","","Four solo winds join Ilia: flute, oboe, horn, bassoon. Her first singer, Dorothea Wendling, was a flautist’s wife.","Mozart to his father Leopold, Munich, 8 Nov 1780, planning this aria “in concert with four wind instruments”","https://www.gutenberg.org/files/5307/5307-h/5307-h.htm","Listen for it",25,1],["ido-c15","c","Fuor del mar","","Mozart wrote this role for Anton Raaff, a 66-year-old star who had sung with Farinelli. It was his last.",null,"https://en.wikipedia.org/wiki/Anton_Raaff","Behind the music",25,1],["ido-c16","a","^Act\\ II:\\ Idol\\ mio,\\ se\\ ritroso$","perf:19a5ae2a","For her 2012 Met debut as Queen Elizabeth I, Elza van den Heever shaved her head for the HD close-ups.",null,"https://en.wikipedia.org/wiki/Elza_van_den_Heever","Diva moment",25,1],["ido-c17","r","Odo da lunge","","Munich’s 1781 review raved about the port and Neptune’s temple scenery, and never mentioned Mozart by name.","Munich press notice of the premiere, 1781","https://en.wikipedia.org/wiki/Idomeneo#Performance_history","Meanwhile, in 1781…",20,1],["ido-c18","h","Placido . il mar","","Bon voyage from Sidon, the Cretan port they’re sailing from. Small detail: it’s a fictional city.",null,"https://en.wikipedia.org/wiki/Idomeneo#Act_2","Plot hole alert",25,1],["ido-c19-m8","m","Qual nuovo terrore","production:1982-10-14","Hear the piccolo? It plays only in this storm. A 1982 critic called these perhaps opera’s first realistic tempests.","Critic: F. Warren O’Reilly, Washington Times, reviewing the Met premiere of this Ponnelle staging, Oct 14, 1982","https://en.wikipedia.org/wiki/Idomeneo#Instrumentation","Listen for it",20,1],["ido-c20","a","^Introduction\\ to\\ Act\\ III\\ by\\ Eric\\ Owens$","perf:19a5ae2a","Before he sang, Eric Owens played oboe, taking lessons from Laura Ahlbeck, an oboist in the Met Orchestra.",null,"https://en.wikipedia.org/wiki/Eric_Owens_(bass-baritone)","Did you know?",4,1],["ido-c21","m","Zeffiretti","","“Zeffiretti lusinghieri” means “Zephyrs caressing”: alone in the garden, Ilia asks the breezes to carry her love to Idamante.","Varesco’s libretto (English translation)","https://en.wikipedia.org/wiki/Idomeneo#Act_3","Translation",25,1],["ido-m10","m","Andr. ramingo","","Mozart on this quartet: “there is no single thing in my opera with which I am so pleased.”","Mozart to his father Leopold, Munich, 27 Dec 1780","https://www.gutenberg.org/files/5307/5307-h/5307-h.htm","Mozart’s favorite",25,1],["ido-m11","m","Act III: Marcia$|^Marcia$","","Mozart added this march so the king can enter with his whole suite. Scored simply, to be played mezza voce.","Mozart to his father Leopold, Munich, 3 Jan 1781","https://www.gutenberg.org/files/5307/5307-h/5307-h.htm","Behind the music",15,1],["ido-c22-m12","m","Ha vinto Amore","","Mozart’s plan for Neptune: three trombones (heard only here) and two horns, placed with the voice. The orchestra falls silent.","Mozart to his father Leopold, Munich, 3 Jan 1781","https://www.gutenberg.org/files/5307/5307-h/5307-h.htm","Listen for it",20,1],["ido-c23","r","D.Oreste, d.Ajace","production:1982-10-14","At this staging’s 1982 Met premiere, Hildegard Behrens “literally stopped the show” with this aria, ending in collapse.","F. Warren O’Reilly, Washington Times, reviewing the Met premiere of this Ponnelle staging, Oct 14, 1982","https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0377675","Diva moment",20,1],["ido-c24-m14","m","Scenda Amor","","Home to D major, the overture’s key. Mozart first closed an opera this way here, then in every one after.",null,"https://en.wikipedia.org/wiki/Idomeneo#Overture","Full circle",20,1]],"gap":60},"tosca":{"v":1,"slug":"tosca","title":"Tosca","match":["Tosca"],"facts":[["tosc-01","h","^Opening\\ Credits$","perf:ab9ce405","Today’s matinee is the Met’s 1,017th Tosca. The very first was on 4 February 1901.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0387605","Met milestone",20,1],["tosc-02","a","^Introduction\\ by\\ Ailyn\\ Pérez$","perf:ab9ce405","Host Ailyn Pérez knows this composer from the inside: she sang Puccini’s Mimì at the Met in 2016.",null,"https://en.wikipedia.org/wiki/Ailyn_P%C3%A9rez","Your host",27,1],["tosc-03","m","Ah!\\.\\.\\.Finalmente","","No overture: three loud, strident chords, Scarpia’s motif, then the fugitive Angelotti bursts in.",null,"https://en.wikipedia.org/wiki/Tosca#Music","Listen for it",20,1],["tosc-04","a","^Act\\ I:\\ Ah!\\.\\.\\.Finalmente!$","perf:ab9ce405","Freddie De Tommaso made his Met debut this month as Cavaradossi, opposite Lise Davidsen’s Tosca.",null,"https://en.wikipedia.org/wiki/Freddie_De_Tommaso","Debut alert",200,1],["tosc-05","m","Recondita armonia","","“Recondita armonia”: wait for the sustained high B flat, as the sacristan grumbles a counter-melody.",null,"https://en.wikipedia.org/wiki/Tosca#Act_1_2","Listen for it",20,1],["tosc-06","a","^Act\\ I:\\ Ma\\ con\\ quei\\ cani\\ …\\ Eccellenza$","perf:ab9ce405","Patrick Carfizzi (Sacristan) and Christopher Job (Sciarrone) also sang this staging’s Met opening night, 31 Dec 2017.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0387605","Opening-night alumni",20,1],["tosc-07","m","Mario! Mario! Mario!","","Tosca arrives on her own motif. She’s suspicious, but the music paints her devotion and serenity.",null,"https://en.wikipedia.org/wiki/Tosca#Act_1_2","Listen for it",20,1],["tosc-08","m","Qua l'occhio","","The love duet “Qual’occhio” is Puccini at his most sensuous, with an almost erotic lyricism.",null,"https://en.wikipedia.org/wiki/Tosca#Act_1_2","Listen for it",20,1],["tosc-09","a","^Act\\ I:\\ Or\\ lasciami\\ al\\ lavoro—Qua\\ l'occhio\\ al\\ mondo$","perf:ab9ce405","Lise Davidsen won Operalia in 2015 and debuted at the Met in 2019, as Lisa in The Queen of Spades.",null,"https://en.wikipedia.org/wiki/Lise_Davidsen","Star turn",120,1],["tosc-10","m","Sommo giubilo","","The sacristan and choirboys celebrate Napoleon’s “defeat”: almost the last carefree moments in the opera.",null,"https://en.wikipedia.org/wiki/Tosca#Act_1_2","Savor it",8,1],["tosc-11","m","Un tal baccano","","Scarpia enters on his menacing theme. Then the fugitive motif returns three times, louder each time.",null,"https://en.wikipedia.org/wiki/Tosca#Act_1_2","Listen for it",20,1],["tosc-12","a","^Act\\ I:\\ Or\\ tutto\\ è\\ chiaro$","perf:ab9ce405","Quinn Kelsey started in the Hawaii Opera Theatre chorus in 1991. His Met debut: Schaunard, in 2008.",null,"https://en.wikipedia.org/wiki/Quinn_Kelsey","From the chorus up",20,1],["tosc-13","m","Tre sbirri","","Te Deum: Scarpia’s lustful reverie is sung right alongside the swelling chorus, then he joins the prayer.",null,"https://en.wikipedia.org/wiki/Tosca#Act_1_2","Sacred and profane",20,1],["tosc-14","s","Tosca è un buon falco","production:2017-12-31","McVicar’s staging premiered at the Met’s 2017 New Year’s Eve gala, co-produced with the Bavarian State Opera and La Scala.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0386316","Set piece",20,1],["tosc-15","m","Tosca è un buon falco","","That distant gavotte? Puccini adapted a student exercise by his late brother Michele, so he could “live again”.",null,"https://en.wikipedia.org/wiki/Tosca#Act_2_2","Listen for it",120,1],["tosc-16","m","Ha più forte sapore","","Offstage, Tosca sings a cantata with the chorus, most likely Puccini’s own Cantata a Giove, a lost 1897 work.",null,"https://en.wikipedia.org/wiki/Tosca#Act_2_2","Listen for it",20,1],["tosc-17","m","Floria!\\.\\. Amore","","News of Napoleon’s victory: Cavaradossi’s brief, ringing “Vittoria! Vittoria!” gives the torture scenes only partial relief.",null,"https://en.wikipedia.org/wiki/Tosca#Act_2_2","Listen for it",20,1],["tosc-18","c","Vissi d'arte","","Puccini thought “Vissi d’arte” was a mistake. He considered cutting it, since it held up the action.",null,"https://en.wikipedia.org/wiki/Tosca#Act_2_2","Composer’s verdict",20,1],["tosc-19","a","^Act\\ II:\\ Vedi,\\ le\\ man\\ giunte\\ io\\ stendo\\ a\\ te!$","perf:ab9ce405","Met music director Yannick Nézet-Séguin conducts. In August 2024 the Met extended his contract through 2029–30.",null,"https://en.wikipedia.org/wiki/Yannick_N%C3%A9zet-S%C3%A9guin","On the podium",20,1],["tosc-20","m","Or gli perdono","","“All Rome trembled before him”: Tosca delivers it on one note, a middle C-sharp monotone, sometimes simply spoken.",null,"https://en.wikipedia.org/wiki/Tosca#Act_2_2","Listen for it",20,1],["tosc-21","m","Io de'sospiri","","Act III opens with a 16-bar horn theme. Remember it: the lovers will sing it in their final duet.",null,"https://en.wikipedia.org/wiki/Tosca#Act_3_2","Listen for it",20,1],["tosc-22","c","Io de'sospiri","","These matins bells were researched: Puccini went to Castel Sant’Angelo to hear how they sound from its ramparts.",null,"https://en.wikipedia.org/wiki/Tosca","Behind the music",120,1],["tosc-23","a","^Act\\ III:\\ Mario\\ Cavaradossi\\?\\ A\\ voi$","perf:ab9ce405","De Tommaso grew up hearing Pavarotti in his family’s restaurant. Pavarotti’s last stage role: Cavaradossi, here, in 2004.",null,"https://en.wikipedia.org/wiki/Freddie_De_Tommaso","Full circle",20,1],["tosc-24","m","E lucevan le stelle","","A somber clarinet solo opens “E lucevan le stelle”, in B minor.",null,"https://en.wikipedia.org/wiki/E_lucevan_le_stelle","Listen for it",6,1],["tosc-25","c","E lucevan le stelle","","Puccini insisted on the words “muoio disperato” (I die in despair), and declined advice to bin the aria.",null,"https://en.wikipedia.org/wiki/Tosca#Act_3_2","Composer’s verdict",110,1],["tosc-26","c","O dolci mani","","Ricordi wanted a transcendent love duet here. Puccini’s defense: Tosca is busy teaching Mario to feign death.",null,"https://en.wikipedia.org/wiki/Tosca#Act_3_2","Composer’s verdict",20,1],["tosc-27","m","Come è lunge","","The final bars: the “E lucevan le stelle” theme returns tutta forza, as loudly as possible.",null,"https://en.wikipedia.org/wiki/Tosca#Act_3_2","Listen for it",150,1]],"gap":60},"traviata":{"v":1,"slug":"traviata","title":"La Traviata","match":["La Traviata"],"facts":[["trav-01","h","^Opening\\ Credits$","perf:5af22f91","Today’s matinee is the Met’s 1,042nd Traviata. New York first heard it in 1856, at the Academy of Music.",null,"https://archives.metopera.org/MetOperaSearch/record.jsp?dockey=0387238","Met milestone",20,1],["trav-02","a","^Introduction\\ by\\ host\\ Renée\\ Fleming$","perf:5af22f91","Host Renée Fleming sang Violetta at the Met in 2003, and again on the Met’s tour to Japan in 2006.",null,"https://en.wikipedia.org/wiki/Ren%C3%A9e_Fleming","Your host",48,1],["trav-03","m","Act I: Preludio","","The prelude opens on very soft, very high strings, the frail heroine. Then the love theme, on lower strings.",null,"https://en.wikipedia.org/wiki/La_traviata#Music","Listen for it",21,1],["trav-04","s","Act I: Preludio","production:2018-12-04","Director Michael Mayer won a Tony for Spring Awakening. His Traviata opened at the Met in December 2018.",null,"https://en.wikipedia.org/wiki/Michael_Mayer_(director)","Director’s cut",130,1],["trav-05","m","Dell'invito","","Curtain up, and lively dance tunes take over. Waltz rhythms run through all of Act I: Paris, in three-quarter time.",null,"https://en.wikipedia.org/wiki/La_traviata#Music","Listen for it",20,1],["trav-06","c","Dell'invito","","La traviata is the only one of Verdi’s many operas set entirely indoors.",null,"https://en.wikipedia.org/wiki/La_traviata#Music","Did you know?",140,1],["trav-07","m","Libiamo","","The Brindisi: a drinking song in B-flat major, in a lilting 3/8, marked Allegretto.",null,"https://en.wikipedia.org/wiki/Libiamo_ne'_lieti_calici","Listen for it",20,1],["trav-08","m","Che è ciò","","That offstage band? Verdi sketched its waltzes like a piano score and left the scoring to the bandmaster.",null,"https://en.wikipedia.org/wiki/La_traviata","Listen for it",10,1],["trav-09","a","^Act\\ I:\\ Un\\ dì\\ felice,\\ eterea$","perf:5af22f91","Stephen Costello, our Alfredo, made his Met debut on the 2007–08 opening night, as Arturo in Lucia.",null,"https://en.wikipedia.org/wiki/Stephen_Costello","Met debut",20,1],["trav-10","a","^Act\\ I:\\ È\\ strano!—Ah,\\ fors'è\\ lui\\ che\\ l'anima$","perf:5af22f91","Nadine Sierra at the Met: Ilia in Idomeneo (2017), then Susanna in Figaro the next season. Now, Violetta.",null,"https://en.wikipedia.org/wiki/Nadine_Sierra","Star turn",20,1],["trav-11","m","Sempre libera","","“Sempre libera” is all feverish ornamentation. Savor it: Violetta never needs coloratura again after Act I.",null,"https://en.wikipedia.org/wiki/La_traviata#Music","Listen for it",20,1],["trav-12","h","Lunge da lei","","Verdi wanted a modern-dress setting. La Fenice insisted on the past: “c. 1700”.",null,"https://en.wikipedia.org/wiki/La_traviata","Meanwhile, in 1853…",20,1],["trav-13","h","Annina, donde vieni","","Dumas fils turned his 1848 novel into the 1852 play La Dame aux camélias. Verdi’s opera followed in 1853.",null,"https://en.wikipedia.org/wiki/La_traviata","Source material",20,1],["trav-14","m","Pura siccome","","The great Germont–Violetta duet begins: many sections, the music turning with every shift in the drama.",null,"https://en.wikipedia.org/wiki/La_traviata#Music","Listen for it",20,1],["trav-15","a","^Act\\ II:\\ Un\\ dì,\\ quando\\ le\\ veneri$","perf:5af22f91","Luca Salsi, our Germont, once sang twice at the Met in a day: Ernani on 30 minutes’ notice, then Lucia.",null,"https://en.wikipedia.org/wiki/Luca_Salsi","Double shift",20,1],["trav-16","c","Alfredo, Alfredo, di questo core","","At the Venice premiere, Act II is where the audience turned. Verdi next day: “La traviata last night a failure.”","Verdi to his friend Emanuele Muzio, the day after the premiere (6 March 1853)","https://en.wikipedia.org/wiki/La_traviata","Meanwhile, in 1853…",20,1],["trav-17","m","Act III: Preludio","","Violetta’s music has traveled: hectic coloratura in Act I, drama in Act II, and now a spiritual quality.",null,"https://en.wikipedia.org/wiki/La_traviata#Music","Listen for it",20,1],["trav-18","h","Act III: Annina\\?","","Revised, it triumphed in Venice in 1854. Librettist Piave: “Then it was a fiasco; now it has created a furore.”","Francesco Maria Piave, on the revival at Venice’s Teatro San Benedetto, 6 May 1854","https://en.wikipedia.org/wiki/La_traviata","Plot twist",20,1],["trav-19","a","^Act\\ III:\\ Teneste\\ la\\ promessa\\ \\.\\.\\.\\ Addio\\ del\\ passato$","perf:5af22f91","Nadine Sierra received the 2018 Beverly Sills Artist Award, in a ceremony held right here at the Met.",null,"https://en.wikipedia.org/wiki/Nadine_Sierra","Award night",20,1],["trav-20","a","^Act\\ III:\\ Parigi,\\ o\\ cara$","perf:5af22f91","A whale of a credit: in 2010 Stephen Costello created Greenhorn (Ishmael) in Jake Heggie’s Moby-Dick.",null,"https://en.wikipedia.org/wiki/Stephen_Costello","Did you know?",20,1]],"gap":60}};
